package kr.ai.noastudio;

import android.app.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.Executor;
import java.util.function.Consumer;

/** Native playlist editor; audio and the upload WebView remain in the common shell. */
final class PlaylistPanel extends LinearLayout {
 private final Activity activity;private final NativePlaylistRepository repo;private final Executor executor;private final List<JSONObject> songs;private final Consumer<JSONArray> play;
 private final int fg,panel,line;private final TextView message;private final LinearLayout rows;private final Button create;private JSONObject session;private String cookie;private boolean busy;private int generation;
 interface Task {void run()throws Exception;}
 PlaylistPanel(Activity a,NativePlaylistRepository r,Executor e,List<JSONObject> catalog,Consumer<JSONArray> p,Runnable account,int foreground,int surface,int border){
  super(a);activity=a;repo=r;executor=e;songs=catalog;play=p;fg=foreground;panel=surface;line=border;setOrientation(VERTICAL);setPadding(dp(16),dp(12),dp(16),dp(8));addView(label("MY PLAYLIST",24));message=label("재생목록을 불러오는 중입니다.",13);addView(message);Button accountButton=button("계정 재생목록 관리",account);accountButton.setOnClickListener(v->account.run());addView(accountButton);
  create=button("새 재생목록",()->name(null));create.setEnabled(false);addView(create);ScrollView scroll=new ScrollView(a);rows=new LinearLayout(a);rows.setOrientation(VERTICAL);scroll.addView(rows);addView(scroll,new LayoutParams(-1,0,1));reload();
 }
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView label(String value,int size){TextView v=new TextView(activity);v.setText(value);v.setTextColor(fg);v.setTextSize(size);v.setPadding(dp(4),dp(8),dp(4),dp(8));return v;}
 private Button button(String title,Runnable action){Button b=new Button(activity);b.setText(title);b.setContentDescription(title);b.setTextColor(fg);b.setAllCaps(false);b.setTextSize(13);b.setMinHeight(dp(48));b.setPadding(dp(12),dp(4),dp(12),dp(4));GradientDrawable bg=new GradientDrawable();bg.setColor(panel);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),line);b.setBackground(bg);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private void reload(){cookie=repo.cookie();int ticket=++generation;busy=true;create.setEnabled(false);executor.execute(()->{try{JSONObject data=repo.lists(cookie);activity.runOnUiThread(()->{if(ticket!=generation||activity.isDestroyed())return;session=data;busy=false;create.setEnabled(true);render();});}catch(Exception e){activity.runOnUiThread(()->{if(ticket!=generation||activity.isDestroyed())return;busy=false;message.setText("재생목록을 불러오지 못했습니다.");rows.removeAllViews();rows.addView(button("다시 불러오기",this::reload));});}});}
 private void render(){message.setText(session.optBoolean("guest")?"이 기기의 임시 재생목록":"계정 재생목록");rows.removeAllViews();JSONArray items=session.optJSONArray("items");if(items==null)return;for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;LinearLayout row=new LinearLayout(activity);Button start=button(item.optString("title"),()->play.accept(item.optJSONArray("tracks")));start.setMaxLines(2);row.addView(start,new LayoutParams(0,-2,1));Button edit=button("편집",()->edit(item));edit.setContentDescription(item.optString("title")+" 편집");row.addView(edit,new LayoutParams(dp(64),-1));LayoutParams lp=new LayoutParams(-1,-2);lp.bottomMargin=dp(8);rows.addView(row,lp);}}
 private void mutate(Task action){if(busy)return;busy=true;create.setEnabled(false);message.setText("저장 중입니다.");executor.execute(()->{try{action.run();activity.runOnUiThread(()->{if(activity.isDestroyed())return;busy=false;if(getParent()!=null)reload();});}catch(Exception e){activity.runOnUiThread(()->{if(activity.isDestroyed())return;busy=false;create.setEnabled(true);message.setText(e instanceof java.io.IOException?e.getMessage():"저장하지 못했습니다. 다시 시도해 주세요.");if(getParent()!=null){rows.addView(button("다시 불러오기",this::reload));}/* Keep the original visible snapshot after failure. */});}});}
 private void name(JSONObject item){EditText input=new EditText(activity);input.setSingleLine();input.setTextColor(fg);input.setText(item==null?"":item.optString("title"));input.setSelectAllOnFocus(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(320)});AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(item==null?"새 재생목록":"이름 변경").setView(input).setNegativeButton("취소",null).setPositiveButton("저장",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String title=input.getText().toString().trim();if(title.isEmpty()||title.codePointCount(0,title.length())>160){input.setError("이름은 1~160자로 입력해 주세요.");return;}dialog.dismiss();mutate(()->{if(item==null)repo.create(session,title,cookie);else repo.save(session,item,title,item.getJSONArray("tracks"),cookie);});}));dialog.show();}
 private String title(String key){for(JSONObject song:songs)if(key.equals(song.optString("key")))return song.optString("title");return "등록된 곡 · 현재 목록에서 찾을 수 없음";}
 private void edit(JSONObject item){
  try{JSONArray working=new JSONArray(item.getJSONArray("tracks").toString());final AlertDialog[] active=new AlertDialog[1];LinearLayout content=new LinearLayout(activity);content.setOrientation(VERTICAL);content.addView(button("이름 변경",()->{active[0].dismiss();name(item);}));if(session.optBoolean("guest"))content.addView(button("재생목록 삭제",()->new AlertDialog.Builder(activity).setTitle("이 재생목록을 삭제할까요?").setMessage("목록에 담긴 곡은 음원에서 계속 찾을 수 있습니다.").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{active[0].dismiss();mutate(()->repo.deleteGuest(session,item));}).show()));ScrollView scroll=new ScrollView(activity);LinearLayout tracks=new LinearLayout(activity);tracks.setOrientation(VERTICAL);scroll.addView(tracks);content.addView(scroll,new LayoutParams(-1,0,1));Runnable render=()->renderTracks(tracks,working);render.run();AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(item.optString("title")).setView(content).setNegativeButton("취소",null).setPositiveButton("곡 변경 저장",(d,w)->mutate(()->repo.save(session,item,item.getString("title"),working,cookie))).create();active[0]=dialog;dialog.setOnShowListener(d->{dialog.getWindow().setLayout(-1,Math.min(dp(600),(int)(getResources().getDisplayMetrics().heightPixels*.85)));});dialog.show();
  }catch(Exception e){message.setText("재생목록을 다시 열어 주세요.");}
 }
 private void renderTracks(LinearLayout host,JSONArray working){host.removeAllViews();if(working.length()==0)host.addView(label("담긴 곡이 없습니다. MUSIC에서 곡을 담아 주세요.",13));for(int i=0;i<working.length();i++){final int at=i;String name=title(working.optString(i));host.addView(button((i+1)+" · "+name,()->{List<String> actions=new ArrayList<>();if(at>0)actions.add("위로 이동");if(at<working.length()-1)actions.add("아래로 이동");actions.add("곡 제거");new AlertDialog.Builder(activity).setTitle(name).setItems(actions.toArray(new String[0]),(d,index)->{try{String action=actions.get(index);if(action.equals("곡 제거"))working.remove(at);else{int next=at+(action.equals("위로 이동")?-1:1);Object held=working.get(at);working.put(at,working.get(next));working.put(next,held);}renderTracks(host,working);}catch(JSONException ignored){message.setText("곡 목록을 다시 열어 주세요.");}}).show();}));}}
}
